(function($){'use strict';var SECTION_SELECTOR='.elementor-control-section_global_colors';var MODE_CTRL_SELECTOR='.elementor-control-ecs_view_mode';var INPUT_SELECTOR='input[name*="elementor-choose-ecs_view_mode"]';var REPEATERS=['system_colors','custom_colors'];var CLASS_MODE_DEFAULT='ecs-mode-default';var CLASS_MODE_DARK='ecs-mode-dark';function getSection(){return $('#elementor-panel').find(SECTION_SELECTOR);}
function applyMode(mode){var $section=getSection();if(!$section.length){return;}
var $target=$section.closest('.elementor-controls-stack');if(!$target.length){$target=$section;}
$target.toggleClass(CLASS_MODE_DEFAULT,mode!=='dark').toggleClass(CLASS_MODE_DARK,mode==='dark');$(INPUT_SELECTOR+'[value="'+mode+'"]').prop('checked',true);if(mode==='dark'){refreshFallbackSwatches($target);}}
function refreshFallbackSwatches($section){REPEATERS.forEach(function(repeater){var $rows=$section.find('.elementor-control-'+repeater+' .elementor-repeater-row-controls');$rows.each(function(){var $row=$(this);var $darkInput=$row.find('.elementor-control-dark_color input[type="text"], .elementor-control-dark_color .pickr');var $colorEl=$row.find('.elementor-control-color');var $darkEl=$row.find('.elementor-control-dark_color');var defaultVal=$colorEl.find('input[type="text"]').val()||'';var darkVal=$darkEl.find('input[type="text"]').val()||'';$darkEl.toggleClass('ecs-dark-fallback',!darkVal&&!!defaultVal);if(!darkVal&&defaultVal){var $swatch=$darkEl.find('.ecs-fallback-swatch');if(!$swatch.length){$swatch=$('<span class="ecs-fallback-swatch"></span>');$darkEl.find('.elementor-control-field').append($swatch);}
$swatch.css('background-color',defaultVal).attr('title','Fallback: '+defaultVal);}else{$darkEl.find('.ecs-fallback-swatch').remove();}});});}
function init(){applyModeFromKit();try{var panelView=elementor.getPanelView();if(panelView){panelView.on('set:page',applyModeFromKit);}}catch(e){}
$('#elementor-panel').on('change.ecs_colour_mode',INPUT_SELECTOR,function(){var mode=$(MODE_CTRL_SELECTOR).find('.elementor-choices input:checked').val()||$(this).val()||'default';applyMode(mode);});$('#elementor-panel').on('click.ecs_colour_mode',MODE_CTRL_SELECTOR+' label',function(){setTimeout(function(){var mode=$(MODE_CTRL_SELECTOR).find('.elementor-choices input:checked').val()||'default';applyMode(mode);},0);});$('#elementor-panel').on('input.ecs_colour_fallback','.elementor-control-system_colors input, .elementor-control-custom_colors input',function(){var $section=getSection();var $target=$section.length?$section.closest('.elementor-controls-stack'):$();if($target.hasClass(CLASS_MODE_DARK)){refreshFallbackSwatches($target);}});var panelEl=document.getElementById('elementor-panel');if(panelEl&&window.MutationObserver){new MutationObserver(function(){var $section=getSection();if(!$section.length){return;}
var $target=$section.closest('.elementor-controls-stack');if(!$target.length){$target=$section;}
if(!$target.hasClass(CLASS_MODE_DEFAULT)&&!$target.hasClass(CLASS_MODE_DARK)){applyModeFromKit();}}).observe(panelEl,{childList:true,subtree:true});}}
function applyModeFromKit(){setTimeout(function(){applyMode('default');},100);}
$(window).on('elementor:init',function(){elementor.on('panel:init',function(){init();});});if(window.elementor){init();}})(jQuery);